"""The spike's low-poly test mesh, generated by script (no binaries in the repo)."""

from __future__ import annotations

from pathlib import Path

from make import blender


def build_test_mesh(out: Path) -> Path:
    """Write a .blend with one UV-mapped low-poly bust ("TestMesh") facing -Y."""
    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)
    blender.run("build_test_mesh", {"out": str(out)})
    return out
